export const meta = {
  name: 'treams-unify-understand',
  description: 'Map duplication, portability, perf mechanics and guards for unifying the treams-rs NumPy API onto the framework backend',
  phases: [
    { title: 'Understand', detail: 'four read-only mappers over the Python layers, native costs and benchmarks' },
  ],
}

const CONTEXT = `
Repository: treams-rs (Rust numerical core + Python package in python/treams_rs). Upstream reference treams is cloned at scratch: treams (only if useful).

Background. The Python package has two separate layers that both compose native operations:
 (1) The NumPy public API: python/treams_rs/_core.py, _array.py, _tmatrix.py, _smatrix.py, _operators.py, _physics.py, _plane.py, _source.py, _lattice.py, iterative.py, ebcm.py, operators.py, misc.py, plus thin wrappers (special.py, sw.py, cw.py, pw.py, lattice.py, coeffs.py).
 (2) A framework-generic physics layer python/treams_rs/_framework.py with class Backend(xp, call, torch=..., validate=...). Backend.invoke(record, shape, *values) wraps a native "recording" (a function returning (value, context) or (value, pullback)) as a framework primitive; everything else is written against b.xp (jax.numpy / torch / advect.numpy). advect.py, jax.py and torch.py each instantiate a Backend (search for "_physics.Backend(").
 python/treams_rs/diff.py holds thin wrappers over the PyO3 module _native that return (value, context).

Proposal being evaluated: make the NumPy API delegate its numerical compositions to the framework-generic code via a NumPy backend (roughly Backend(np, call=lambda record, shape, *v, real=False: record(*v)[0])), so each feature is implemented once, and the sanctioned Python-only contribution route becomes "compose existing diff/native primitives in backend-generic code". The user's question: would this be possible WITHOUT a significant amount of added code and WITHOUT a performance regression versus the current treams-rs NumPy API?

Rules: READ-ONLY. Do not modify any file under treams-rs. Cite file:line for every claim. Count lines with wc/sed rather than guessing. Be concrete and skeptical; if something is uncertain say so.`

const DUP_SCHEMA = {
  type: 'object',
  properties: {
    duplicates: { type: 'array', items: { type: 'object', properties: {
      operation: { type: 'string' },
      numpy_location: { type: 'string' },
      framework_location: { type: 'string' },
      numpy_lines: { type: 'integer' },
      framework_lines: { type: 'integer' },
      native_entry_numpy: { type: 'string', description: 'which diff/_native function(s) the NumPy version calls' },
      native_entry_framework: { type: 'string' },
      semantic_differences: { type: 'string', description: 'validation, supported cases (local/global, cylindrical, parity, absorbing media...), return types, error messages' },
      drop_in_replaceable: { type: 'boolean', description: 'could the NumPy version be replaced by calling the framework version with a NumPy backend without changing public behavior?' },
      what_would_need_to_change: { type: 'string' },
    }, required: ['operation','numpy_location','framework_location','numpy_lines','framework_lines','semantic_differences','drop_in_replaceable','what_would_need_to_change'] } },
    total_duplicated_numpy_lines: { type: 'integer' },
    total_duplicated_framework_lines: { type: 'integer' },
    summary: { type: 'string' },
  },
  required: ['duplicates','total_duplicated_numpy_lines','total_duplicated_framework_lines','summary'],
}

const SURFACE_SCHEMA = {
  type: 'object',
  properties: {
    items: { type: 'array', items: { type: 'object', properties: {
      name: { type: 'string' },
      location: { type: 'string' },
      lines: { type: 'integer' },
      category: { type: 'string', enum: ['metadata_or_bookkeeping','composable_backend_generic','blocked_or_awkward'] },
      reason: { type: 'string', description: 'why this category; for blocked: the concrete obstacle (in-place mutation, PhysicsArray semantics, stateful factor objects, numpy-only APIs, lazy evaluation, strided views, etc.)' },
      port_effort_lines: { type: 'integer', description: 'estimated net new framework-side lines to make it backend-generic (0 for metadata)' },
    }, required: ['name','location','lines','category','reason','port_effort_lines'] } },
    framework_missing_capabilities: { type: 'array', items: { type: 'string' }, description: 'capabilities the Backend/framework layer lacks that a full unification would need (e.g. index assignment, block assembly helper, linalg, dtype handling)' },
    summary: { type: 'string' },
  },
  required: ['items','framework_missing_capabilities','summary'],
}

const PERF_SCHEMA = {
  type: 'object',
  properties: {
    findings: { type: 'array', items: { type: 'object', properties: {
      topic: { type: 'string' },
      location: { type: 'string' },
      description: { type: 'string' },
      impact: { type: 'string', enum: ['none','small_constant_overhead','scales_with_problem_size','large'] },
      mitigation: { type: 'string' },
    }, required: ['topic','location','description','impact','mitigation'] } },
    native_recording_cost: { type: 'string', description: 'Does the NumPy API already call recording (context-returning) native entry points? Do those retain residuals (memory/time) compared to a non-recording forward? Are there non-recording forward entry points?' },
    summary: { type: 'string' },
  },
  required: ['findings','native_recording_cost','summary'],
}

const GUARD_SCHEMA = {
  type: 'object',
  properties: {
    benchmarks: { type: 'array', items: { type: 'object', properties: {
      script: { type: 'string' },
      workloads: { type: 'string' },
      exercises_python_numpy_layer: { type: 'string', description: 'which public NumPy-API calls it times, or "native only"' },
      gates: { type: 'string', description: 'what it compares against and the pass criteria' },
    }, required: ['script','workloads','exercises_python_numpy_layer','gates'] } },
    behavior_tests: { type: 'array', items: { type: 'string' }, description: 'test files that pin NumPy-API behaviour of the duplicated operations' },
    adapter_call_contract: { type: 'string', description: 'what advect/jax/torch _physics_call do (shape checks, real projection, validation, residual handling) and therefore what a minimal NumPy backend call must replicate or may skip' },
    suggested_microbenchmarks: { type: 'array', items: { type: 'string' }, description: 'concrete public calls + sizes that would expose Python-overhead regressions (small problems) and algorithmic regressions (large problems)' },
    summary: { type: 'string' },
  },
  required: ['benchmarks','behavior_tests','adapter_call_contract','suggested_microbenchmarks','summary'],
}

phase('Understand')
const [dup, surface, perf, guards] = await parallel([
  () => agent(`${CONTEXT}

YOUR TASK: build a complete inventory of operations implemented TWICE — once in the NumPy API and once in _framework.py (e.g. cross sections, scatter, cluster solve/scatter, polarization change, wave expansion into a basis, fields, S-matrix cascade/power/scatter/bands, periodic solve, layer stack, propagation, multilayer construction...). For each pair read both implementations fully and record the fields in the schema. Pay close attention to semantic differences that would block drop-in replacement: support for local (multi-origin) vs global matrices, cylindrical vs spherical, parity vs helicity, absorbing media, error types/messages, return types (PhysicsArray vs plain array, NamedTuples), and which native entry points are called (e.g. NumPy cluster uses diff.particle_cluster while framework Cluster uses diff.interaction on a dense block-diagonal — confirm or refute). Sum the line counts.`, { label: 'duplication-inventory', phase: 'Understand', schema: DUP_SCHEMA }),

  () => agent(`${CONTEXT}

YOUR TASK: inventory the NumPy-API surface that has NO counterpart in _framework.py (operators in _operators.py, Operator classes, PhysicsArray/_array.py, basis classes, lattice/periodic helpers, PeriodicWave, ScatteringFactor, interaction factor objects, iterative.py, ebcm.py, io-related numerics, chirality_density/poynting in _smatrix.py, valid_points, TMatrixC specifics, etc.). For every public class/function/method that does numerical work, classify it: metadata_or_bookkeeping (no change needed under unification), composable_backend_generic (could be written once against b.xp + b.invoke with modest effort), or blocked_or_awkward (give the concrete obstacle). Estimate net new lines to port each composable item. Also list capabilities the Backend/framework layer is missing for a full unification. Finally give an honest total: how many lines would a FULL unification add, how many would it delete, and how many would a PARTIAL unification (only the already-duplicated operations) add/delete.`, { label: 'numpy-only-surface', phase: 'Understand', schema: SURFACE_SCHEMA }),

  () => agent(`${CONTEXT}

YOUR TASK: analyse the PERFORMANCE consequences of routing the NumPy API through the framework-generic code with a NumPy backend. Investigate at least:
 - Per-call Python overhead in _framework.py on a NumPy backend: Backend.array/stack/concat/match (metadata stacking + extra invoke per operation), Backend.ks recomputation, closures, validate hooks, conversions between list/tuple and arrays.
 - Algorithmic differences: e.g. framework Cluster._local builds a dense block-diagonal by nested concat of zero blocks (O(N^2) Python calls for N particles) while the NumPy API passes per-particle blocks to native code; framework cross sections build an overlap expansion even for global matrices; any place where one layer uses a specialised native path (particle_cluster, factor objects, matrix-free iterative, requested-illumination) and the other a dense generic one. Quantify the asymptotics.
 - Native side: does the NumPy API already call context-returning (recording) native functions via diff.*? Read the Rust code in crates/treams-core/src and crates/treams-py/src for interact/expansion/smatrix_add/particle_cluster/illuminate etc. to see what residuals the forward retains (copies of inputs, LU factors, inverses) and whether a non-recording forward exists. If the NumPy API already pays that cost, unification adds nothing there; if it uses cheaper non-recording entry points, unification would add cost — determine which.
 - GIL/threading or copy behaviour (ascontiguousarray copies, complex casts) that differs between the layers.
For each finding give impact and a concrete mitigation (e.g. a NumPy-backend fast path, a block-assembly helper, using particle_cluster in the framework layer too).`, { label: 'perf-mechanics', phase: 'Understand', schema: PERF_SCHEMA }),

  () => agent(`${CONTEXT}

YOUR TASK: map the guards that would detect a regression from this refactor.
 - Benchmarks: read docs/benchmarks.md, docs/benchmark-comparison.md, the justfile bench recipes and scripts/benchmark_*.py (and anything in benchmarks/). For each benchmark: workloads, whether it times public NumPy-API Python calls or only native kernels, and its gates (vs upstream treams? vs previous treams-rs?). State plainly whether any existing gate would catch a slowdown of the treams-rs NumPy Python layer relative to its current self.
 - Tests: which tests pin behaviour of the operations that exist in both layers (cross sections, scatter, cluster, polarization, S-matrix cascade/power/bands, periodic solve, layer stack).
 - Adapter contract: read the _physics_call functions in advect.py, jax.py, torch.py and Backend in _framework.py; describe what a NumPy backend 'call' must do (and may skip) — shape/dtype checks, real projection, residual disposal.
 - Suggest a concrete microbenchmark set (exact public calls and sizes: small lmax/few particles where Python overhead dominates, and large lmax/many particles where native work dominates) that a prototype should run to decide the "no performance regression" question.`, { label: 'guards-benchmarks', phase: 'Understand', schema: GUARD_SCHEMA }),
])

return { dup, surface, perf, guards }
export const meta = {
  name: 'treams-unify-prototype',
  description: 'Prototype framework fixes + NumPy-backend delegation in scratch copies, test, benchmark, review, and re-measure',
  phases: [
    { title: 'Implement', detail: 'one implementer per domain in its own scratch copy' },
    { title: 'Benchmark', detail: 'paired baseline vs candidate microbenchmarks per domain' },
    { title: 'Review', detail: 'adversarial semantic, gradient and line-count review per domain' },
    { title: 'Quiet re-run', detail: 'single agent re-measures key cases with nothing else running' },
  ],
}

const S = 'scratch'

const COMMON = `
Repository (DO NOT MODIFY anything under it): treams-rs. Python package: python/treams_rs. A RELEASE build of the native extension is already installed (python/treams_rs/_native.cpython-313-x86_64-linux-gnu.so; the venv is .venv, an editable .pth points at python). Use .venv/bin/python directly (do not run uv sync or rebuild). Always set PYTHONDONTWRITEBYTECODE=1. A scratch copy of the package placed at <dir>/treams_rs shadows the installed one when run with PYTHONPATH=<dir> (verified). Run pytest from treams-rs so its conftest/config apply, e.g.:
  cd treams-rs && PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=<dir> .venv/bin/python -m pytest -q -p no:cacheprovider tests/test_x.py
Confirm with a one-liner that treams_rs.__file__ resolves into <dir> before trusting any result.

Prior analysis (read it first, it is long; it has file:line references and measured numbers): ${S}/understand.json with keys dup (29 duplicated operation pairs between the NumPy API and _framework.py, semantic differences), surface (NumPy-only surface, missing framework capabilities, line estimates), perf (performance mechanics and the concrete fixes), guards (benchmarks, adapter call contract, suggested microbenchmarks). Earlier probe/benchmark scripts are in ${S} (bench/, bench.py, proto*.py, prof*.py, sem.py) and may be reused.

The question being answered for the user: can the treams-rs NumPy API be made to delegate its numerical compositions to the framework-generic layer (python/treams_rs/_framework.py, Backend(xp, call)) via a NumPy backend — so each feature is implemented once and Python-only contributors write backend-generic code — WITHOUT a significant amount of added code and WITHOUT a performance regression versus the current NumPy API? The prior analysis says naive delegation regresses badly (unconditional overlap expansion in cross_sections, O(n^2) Python loop in layer_stack, dense cluster path, recording-only entry points, ~250us fixed overhead) and that 0/29 pairs are drop-in, but that most slowdowns are fixable inside _framework.py. Your job is to TEST that hypothesis with real code, honestly. Do not cheat: a "facade" that keeps the old NumPy implementation and merely calls the framework for nothing does not count as delegation. If something cannot be delegated without breaking behaviour or performance, keep the NumPy code for it and record why — that is a valid, important result.`

const DOMAINS = [
  {
    key: 'tmatrix',
    dir: `${S}/cand_tmatrix`,
    scope: `T-MATRIX / WAVES DOMAIN. Framework fixes to attempt (backend-generic, must keep JAX/torch/advect gradients correct): (1) cross_sections/cross_widths: skip the overlap expansion for a global (single-origin) basis and match NumPy's zero-weighting of evanescent cylindrical sectors; (2) Cluster.solve via diff.particle_cluster with per-particle blocks and Cluster.scatter via diff.factor_interaction_blocks (both have pullbacks) instead of a dense block-diagonal; (3) D/B/G/F fields with one weighted native field call instead of separate E and H calls; (4) plane-wave expansion and per-call overhead (Backend.match / Backend.ks / record closures) — add a value-only (non-recording) mode on Backend so a NumPy backend can use cheaper non-recording native entry points and skip validation-record plumbing where it is pure overhead. Then add a NumPy backend and make the NumPy API delegate these duplicated operations: TMatrix/TMatrixC cross sections (xs, xw, cross_sections, cross_widths), scatter, cluster solve and scatter (both _tmatrix._Interaction and _physics.Cluster paths), MultipoleWave/PlaneWave field evaluation incl. D/B/G/F, and polarization change — preserving the public NumPy semantics (return types, PhysicsArray/read-only arrays, Python floats, batches of illuminations, local multi-origin matrices, parity, config default poltype, error types/messages).`,
    tests: 'tests/test_api.py tests/test_physics_api.py tests/test_particle_cluster.py tests/test_fields.py tests/test_field_operators.py tests/test_framework_physics.py tests/test_matrix_conveniences.py tests/test_operator_objects.py tests/test_periodic_conversion.py tests/test_cylinder.py tests/test_illumination.py tests/test_polarization.py tests/test_jax.py tests/test_torch.py tests/test_advect.py',
  },
  {
    key: 'smatrix',
    dir: `${S}/cand_smatrix`,
    scope: `S-MATRIX / PLANAR / PERIODIC DOMAIN. Framework fixes to attempt (backend-generic, must keep JAX/torch/advect gradients correct): (1) layer_stack: replace the O(n^2) per-scalar b.stack assembly with vectorised gather/mask assembly; (2) compact-block parity transforms instead of dense change@A@change.T for planar stacks; (3) SMatrix.power: vectorise port matching in _incident and use the non-recording transmittance when the backend is value-only; (4) cascade/bands per-call overhead (match/ks/metadata records) — add a value-only (non-recording) mode on Backend so a NumPy backend can skip recording-only cost. Also determine which layer is CORRECT for the partial-polarization slab discrepancy reported in understand.json (compare against upstream treams in ${S}/treams if importable, or against physical invariants such as energy conservation/reciprocity for a lossless slab) — this may be a real bug in one layer. Then add a NumPy backend and make the NumPy API delegate these duplicated operations: interface/slab/multilayer_slab/propagation/stack, SMatrix cascade, power/tr, scatter, bands, solve_periodic and PeriodicResponse.to_smatrix — preserving the public NumPy semantics (return types, read-only arrays, Python floats, batches, parity, config default poltype, Lattice/WaveVector metadata, error types/messages).`,
    tests: 'tests/test_api.py tests/test_physics_api.py tests/test_layers.py tests/test_plane.py tests/test_plane_basis.py tests/test_plane_transforms.py tests/test_periodic_conversion.py tests/test_periodic_callbacks.py tests/test_channels.py tests/test_internal_bands.py tests/test_framework_physics.py tests/test_matrix_conveniences.py tests/test_jax.py tests/test_torch.py tests/test_advect.py',
  },
]

const IMPL_SCHEMA = {
  type: 'object',
  properties: {
    candidate_dir: { type: 'string' },
    framework_fixes: { type: 'array', items: { type: 'object', properties: {
      change: { type: 'string' }, location: { type: 'string' }, lines_added: { type: 'integer' }, lines_removed: { type: 'integer' }, done: { type: 'boolean' },
    }, required: ['change','location','lines_added','lines_removed','done'] } },
    delegated: { type: 'array', items: { type: 'object', properties: {
      numpy_method: { type: 'string' }, status: { type: 'string', enum: ['delegated','kept_numpy','partial'] }, reason: { type: 'string' },
    }, required: ['numpy_method','status','reason'] } },
    line_delta: { type: 'object', properties: {
      framework_added: { type: 'integer' }, framework_removed: { type: 'integer' },
      numpy_api_added: { type: 'integer' }, numpy_api_removed: { type: 'integer' },
      other_added: { type: 'integer' }, other_removed: { type: 'integer' },
      net: { type: 'integer' }, how_counted: { type: 'string' },
    }, required: ['framework_added','framework_removed','numpy_api_added','numpy_api_removed','net','how_counted'] },
    tests: { type: 'object', properties: {
      command: { type: 'string' }, baseline_result: { type: 'string' }, candidate_result: { type: 'string' }, new_failures: { type: 'array', items: { type: 'string' } },
    }, required: ['command','baseline_result','candidate_result','new_failures'] },
    semantic_changes_remaining: { type: 'array', items: { type: 'string' } },
    correctness_findings: { type: 'array', items: { type: 'string' }, description: 'bugs found in either layer while doing this (e.g. which slab result is right)' },
    gradient_tests_needed: { type: 'array', items: { type: 'string' }, description: 'framework operations that became newly differentiable or changed and would need gradient tests per repo rules' },
    summary: { type: 'string' },
  },
  required: ['candidate_dir','framework_fixes','delegated','line_delta','tests','semantic_changes_remaining','correctness_findings','gradient_tests_needed','summary'],
}

const BENCH_SCHEMA = {
  type: 'object',
  properties: {
    protocol: { type: 'string' },
    cases: { type: 'array', items: { type: 'object', properties: {
      case: { type: 'string' }, size: { type: 'string' }, baseline_us: { type: 'number' }, candidate_us: { type: 'number' }, ratio: { type: 'number', description: 'candidate/baseline; >1 means slower' }, spread: { type: 'string' },
    }, required: ['case','size','baseline_us','candidate_us','ratio','spread'] } },
    adapter_cases: { type: 'array', items: { type: 'object', properties: {
      case: { type: 'string' }, framework: { type: 'string' }, baseline_us: { type: 'number' }, candidate_us: { type: 'number' }, ratio: { type: 'number' },
    }, required: ['case','framework','baseline_us','candidate_us','ratio'] } },
    regressions: { type: 'array', items: { type: 'string' } },
    summary: { type: 'string' },
  },
  required: ['protocol','cases','adapter_cases','regressions','summary'],
}

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    semantic_issues: { type: 'array', items: { type: 'object', properties: {
      issue: { type: 'string' }, severity: { type: 'string', enum: ['blocking','minor','cosmetic'] }, evidence: { type: 'string' },
    }, required: ['issue','severity','evidence'] } },
    fake_delegation: { type: 'array', items: { type: 'string' }, description: 'places where the NumPy API claims to delegate but effectively kept its own implementation' },
    gradient_check: { type: 'string', description: 'what you ran (testing.check_gradient / adapter tests) on the changed framework operations and the result' },
    line_count_check: { type: 'string', description: 'your own measurement of added/removed lines vs the implementer claim' },
    verdict: { type: 'string', enum: ['claims_hold','claims_partly_hold','claims_do_not_hold'] },
    summary: { type: 'string' },
  },
  required: ['semantic_issues','fake_delegation','gradient_check','line_count_check','verdict','summary'],
}

const results = await pipeline(
  DOMAINS,
  d => agent(`${COMMON}

${d.scope}

Work ONLY in your own scratch copy: rm -rf ${d.dir} && mkdir -p ${d.dir} && cp -r python/treams_rs ${d.dir}/ (this copies the release .so). Another agent works on a different domain in a different copy at the same time; do not touch other directories.
Steps:
 1. Run the baseline test set first (PYTHONPATH unset, i.e. the installed package) and record pass/fail counts, so pre-existing failures are known: ${d.tests}
 2. Implement the framework fixes, a NumPy backend, and the delegation in your copy. Keep code in the repo's style (typed, docstrings where public, ruff-clean if you can run .venv/bin/ruff).
 3. Run the same tests against your copy (PYTHONPATH=${d.dir}). Iterate until no new failures, or document the ones you could not fix and why.
 4. Count lines honestly with: diff -ruN -x '*.so' -x __pycache__ python/treams_rs ${d.dir}/treams_rs, split by file (framework vs NumPy-API modules vs other). Report added/removed/net.
 5. Do a quick sanity timing (a few cases) to make sure you have not made things obviously slower; detailed benchmarking is done by the next stage.
Return the structured result.`, { label: `implement:${d.key}`, phase: 'Implement', schema: IMPL_SCHEMA }),

  (impl, d) => agent(`${COMMON}

You are the BENCHMARK stage for the ${d.key} domain. The implementer's candidate copy is at ${d.dir}/treams_rs; its report:
${JSON.stringify(impl, null, 1)}

Measure candidate vs baseline (installed package) for every operation the implementer changed or delegated, over sizes that span overhead-dominated (small lmax / few ports / one point) to native-dominated (large lmax / many particles or ports / many points). Use the case list in understand.json guards.suggested_microbenchmarks where it applies to this domain. Protocol: the .so is byte-identical (verify sha256 of both .so files). Run baseline and candidate in SEPARATE processes, ALTERNATING (A,B,A,B,... at least 5 rounds each), with RAYON_NUM_THREADS fixed (e.g. 2), calibrating inner loops to >=20 ms per sample, and report median and spread. First assert numerical equality (rtol 1e-12, or explain any difference). Another agent may be running at the same time on this 4-core machine, so rely on alternation and medians, and flag ratios within noise. Also measure the JAX and torch adapters (and advect if quick) on the changed framework operations, baseline vs candidate, since framework fixes should speed them up too. Report ratio = candidate/baseline (>1 = slower) and list every regression >5% (>10% for sub-ms calls) that is outside noise.`, { label: `bench:${d.key}`, phase: 'Benchmark', schema: BENCH_SCHEMA })
    .then(bench => ({ impl, bench })),

  (prev, d) => agent(`${COMMON}

You are an ADVERSARIAL REVIEWER for the ${d.key} domain prototype at ${d.dir}/treams_rs. Default to skepticism: your job is to find where the claims below are wrong.
Implementer report:
${JSON.stringify(prev.impl, null, 1)}
Benchmark report:
${JSON.stringify(prev.bench, null, 1)}

Check: (1) semantic changes in the public NumPy API not caught by tests — probe edge cases directly (return types, read-only flags, Python float vs 0-d array, errors and messages, batches of illuminations, local/multi-origin matrices, parity, chiral media, absorbing media, cylindrical evanescent sectors, config default polarization); (2) fake delegation — NumPy methods that still carry their own numerics; (3) gradient correctness of every changed framework operation through JAX, torch and advect: run treams_rs.testing.check_gradient or the repo's adapter tests against the candidate; (4) re-count lines yourself with diff -ruN -x '*.so' -x __pycache__ against python/treams_rs; (5) spot-check two or three benchmark numbers yourself, especially any claimed parity at small sizes. Keep CPU-heavy work modest because another agent may be benchmarking concurrently. Return the structured verdict.`, { label: `review:${d.key}`, phase: 'Review', schema: REVIEW_SCHEMA })
    .then(review => ({ domain: d.key, dir: d.dir, ...prev, review })),
)

phase('Quiet re-run')
const done = results.filter(Boolean)
const quiet = await agent(`${COMMON}

You are the final QUIET RE-MEASUREMENT. No other agent is running now, so this is the cleanest timing window. Candidate copies: ${done.map(r => `${r.domain}: ${r.dir}/treams_rs`).join('; ')}.
Prior benchmark and review reports:
${JSON.stringify(done.map(r => ({ domain: r.domain, bench: r.bench, review_summary: r.review && r.review.summary, review_verdict: r.review && r.review.verdict })), null, 1)}

Re-measure, candidate vs baseline, alternating separate processes, RAYON_NUM_THREADS=2, >=7 rounds, medians and spread: (a) the five worst ratios reported per domain; (b) the smallest/overhead-dominated case of each delegated operation (single sphere lmax 1-3, 1-2 ports, 1 field point) — this is where fixed Python overhead shows; (c) one large native-dominated case per domain; (d) two adapter cases (JAX) per domain. State plainly, per domain, whether "no performance regression" holds, holds only above some size, or does not hold, and quantify the remaining per-call overhead in microseconds.`, { label: 'quiet-rerun', phase: 'Quiet re-run', schema: BENCH_SCHEMA })

return { domains: done, quiet }
export const meta = {
  name: 'treams-framework-fixes-review',
  description: 'Adversarial multi-lens review of the framework-fix and compare-builds commits, with independent verification of every finding',
  phases: [
    { title: 'Review', detail: 'four lenses over commits a139022f and 1438a234' },
    { title: 'Verify', detail: 'two independent skeptics per finding' },
  ],
}

const COMMON = `
Repository: treams-rs, branch claude/framework-adapter-fixes (pushed). Base: 9317d670 (the improvement branch). Two commits under review:
 - a139022f "perf: solve framework clusters block by block and change polarization pairwise" (python/treams_rs/_framework.py, _framework_backend.py, _framework_smatrix.py, _framework_tmatrix.py, _framework_waves.py, tests/autodiff/test_framework_physics.py, CHANGELOG.md)
 - 1438a234 "feat: compare two Python trees call by call with just bench-compare" (scripts/compare_builds.py, tests/scripts/test_compare_builds.py, justfile, scripts/README.md, docs/development/benchmarks.md, CHANGELOG.md)
See them with: git -C treams-rs show <sha>. Repo rules: AGENTS.md, python/AGENTS.md, docs/development/architecture.md, docs/development/testing.md.

Context: python/treams_rs/_framework*.py is the backend-generic physics layer behind the treams_rs.advect, treams_rs.jax and treams_rs.torch namespaces (Backend(xp, operation); Backend.apply runs a native "record" returning (value, pullback) as a framework op; Backend.guard runs a check in a record). The NumPy public API (_tmatrix.py, _smatrix.py, _cluster.py, _waves.py, _polarization.py, ...) is separate and was NOT changed.

STRICT RESOURCE RULE: a timing benchmark (scripts/compare_builds.py) is running on this 4-core host right now. Do NOT run pytest suites, builds, cargo, ruff on the whole repo, or anything CPU-heavy. You MAY run small single-purpose Python probes (a few seconds each) with: cd treams-rs && PYTHONDONTWRITEBYTECODE=1 RAYON_NUM_THREADS=1 OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 .venv/bin/python -c '...'  (the release extension is installed; jax needs jax.config.update('jax_enable_x64', True)). Do NOT modify any file in the repository and do not run git commands that change state. Scratch files go in scratch: review/.

Report only real defects or concrete risks with evidence (file:line, and a probe output where possible). Do not report style preferences. Severity: blocking (wrong numbers, wrong gradients, crash on a supported input, broken test/CI, rule violation), minor (edge case, misleading message/doc, missing test for a changed path), nit.`

const FINDINGS = {
  type: 'object',
  properties: {
    findings: { type: 'array', items: { type: 'object', properties: {
      title: { type: 'string' },
      severity: { type: 'string', enum: ['blocking', 'minor', 'nit'] },
      location: { type: 'string' },
      evidence: { type: 'string', description: 'what you read or ran, and the output' },
      suggested_fix: { type: 'string' },
    }, required: ['title', 'severity', 'location', 'evidence', 'suggested_fix'] } },
    checked_ok: { type: 'array', items: { type: 'string' }, description: 'things you verified are correct' },
  },
  required: ['findings', 'checked_ok'],
}

const VERDICT = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean', description: 'true if the finding is wrong, not reproducible, or not a defect' },
    reasoning: { type: 'string' },
    evidence: { type: 'string' },
    corrected_severity: { type: 'string', enum: ['blocking', 'minor', 'nit', 'not_a_defect'] },
  },
  required: ['refuted', 'reasoning', 'evidence', 'corrected_severity'],
}

const LENSES = [
  { key: 'polarization', prompt: `LENS: Backend.change_polarization / change_port_polarization (pairwise polarization change replacing dense change @ A @ change.T) and every call site (TMatrix, Wave, PortWave, SMatrix.with_polarization, SMatrix._incident). Check: exact equality with the dense changepoltype operator in BOTH directions, for spherical and cylindrical bases (cylindrical modes carry kz, m, pol), permuted/interleaved mode orders, bases with several positions (cluster bases), port label construction from (group, pol) modes; correct axes for (modes,), (modes, modes) and (2, 2, ports, ports) arrays; behaviour when source == target (previously identity product), invalid names, incomplete pairs; that advanced indexing value[(slice(None),)*axis + (partners,)] and multiplication by a float array are differentiable and dtype-correct in advect.numpy, jax and torch (complex128 kept, no silent cast to float); performance pitfalls for tiny sizes (each axis = gather + 2 mults + add) vs one dense matmul.` },
  { key: 'cluster', prompt: `LENS: framework Cluster.solve now calls diff.particle_cluster inside a record, and Cluster.scatter checks distinct positions inside its record. Check: pullback reordering (positions, ks, *blocks) against ParticleClusterContext.pullback -> (local list, positions, ks) and against the invoke order; real vs complex cotangent conventions for positions (real) and ks (complex) in each adapter; heterogeneous particles (different lmax, cylindrical particles with kz, parity polarization), particle bases with mode subsets; that the native particle_cluster coupling equals the previous b.expansion(singular=True) coupling (helicity and parity) — probe values vs the base commit's dense path (you can reconstruct it with diff.interaction on Cluster._local() and Cluster._coupling()); the distinct-position check (np.unique exact equality) vs what the native check does (tolerance?) — could solve and scatter now disagree on near-coincident inputs; any path that still uses _local()/_coupling() and whether solve_periodic with a Cluster cell is unaffected.` },
  { key: 'achiral', prompt: `LENS: Backend.require_achiral and its call sites (TMatrix.__init__, Wave.__init__, SMatrix.__init__ when polarization == "parity"; Constructors._layers checks interior media). Check: static detection (int/float/complex/np.number/np.ndarray) vs framework values (jax tracers under jit, torch tensors with and without requires_grad, advect arrays) and that the guard path works under jax.jit and jax.grad (callback raises -> error surfaces), torch autograd, advect; false positives (kappa = 0j, -0.0, kappa arrays of zeros, kappa given as numpy 0-d array, kappa None?), objects legitimately created in parity in an achiral medium through internal paths (cascade, scatter, to_smatrix, port waves, periodic responses) — make sure no internal path constructs a parity object with a chiral medium in a way the NumPy API allows; parity layer constructors with chiral interior layer vs NumPy behaviour (_smatrix.py slab check_poltype_medium over all media; interface; multilayer_slab; propagation); whether the extra guard callback changes JAX jit compile behaviour or adds measurable overhead when kappa is a traced value; message text identical to the NumPy API.` },
  { key: 'tooling', prompt: `LENS: scripts/compare_builds.py, tests/scripts/test_compare_builds.py, the justfile recipe bench-compare, scripts/README.md row, docs/development/benchmarks.md paragraph, CHANGELOG entries of both commits. Check: correctness of the ABBA alternation (orders = list(abba(len(names) + index))[index:]) — both trees go first equally often per call across rounds; Worker protocol robustness (worker crash/exception -> clear error, no hang; stderr handling; stdout pollution by warnings from imported libraries printed to stdout would break json parsing?); baseline_from_ref when the ref lacks python/treams_rs or the native check (git diff --quiet ref -- crates Cargo.lock Cargo.toml) — does it also need to consider uncommitted native changes, and is pyproject/maturin config relevant; that the candidate tree's existing __pycache__ or the editable .pth cannot shadow the baseline (PYTHONPATH precedence; check the worker's tree assertion); summarize/agreement semantics; the torch objective calls float() on a tensor requiring grad (UserWarning seen in the run log at scratch: cmp_full2.txt) — should detach; that the call list's public API calls are valid on the base commit too (a call that only exists in the candidate would break --baseline-ref); repository conventions for scripts (module docstring with the run command, README table row, a test, ruff rules) and whether tests/test_suite_rules.py or tests/scripts/test_repository.py or tests/api/test_docs.py impose rules the new files/docs/CHANGELOG text might violate (read those tests; do not run the suites). Also check the CHANGELOG wording against any rule enforced by tests (e.g. history words, absolute links).` },
]

phase('Review')
const results = await pipeline(
  LENSES,
  lens => agent(`${COMMON}\n\n${lens.prompt}\n\nReturn every defect you can substantiate, plus what you verified as correct.`, { label: `review:${lens.key}`, phase: 'Review', schema: FINDINGS }),
  (review, lens) => parallel((review ? review.findings : []).map((f, i) => () =>
    parallel([0, 1].map(k => () => agent(`${COMMON}\n\nYou are an independent SKEPTIC (#${k + 1}). Try to REFUTE this finding from the ${lens.key} review. Re-derive it yourself from the code and, if useful, a small probe. If it is real, say so and give the correct severity. Default to refuted=true only if you cannot substantiate it.\n\nFINDING:\n${JSON.stringify(f, null, 1)}`, { label: `verify:${lens.key}:${i}:${k}`, phase: 'Verify', schema: VERDICT })))
      .then(votes => {
        const v = votes.filter(Boolean)
        const upheld = v.filter(x => !x.refuted).length
        return { lens: lens.key, ...f, upheld_votes: upheld, votes: v.length, verdicts: v, confirmed: upheld >= 1 && v.length > 0 && upheld * 2 >= v.length }
      })
  )).then(findings => ({ lens: lens.key, checked_ok: review ? review.checked_ok : [], findings })),
)

const all = results.filter(Boolean)
const confirmed = all.flatMap(r => r.findings.filter(f => f && f.confirmed))
log(`${confirmed.length} findings survived verification across ${all.length} lenses`)
return { confirmed, lenses: all }
